        switch (b.cur(1).codepoint)
        {
          case 0x0A3Eu: case 0x0A48u: case 0x0A4Cu:
        matched = true;
        break;
        }
        break;
      case 0x0A72u:
        switch (b.cur(1).codepoint)
        {
          case 0x0A3Fu: case 0x0A40u: case 0x0A47u:
        matched = true;
        break;
        }
